mapper.select:
SELECT COALESCE(content, '')
FROM sys_work_chapter
WHERE work_id = #{workId}

    AND chapter_no <= #{episodeTo}

ORDER BY chapter_no ASC, chapter_id ASC

SELECT * FROM sys_demand_stage
WHERE demand_id = #{demandId}
  AND stage_order > #{prevOrder}
ORDER BY stage_order ASC
LIMIT 1

mapper.update:
UPDATE sys_demand_stage
extend_status = #{extendStatus}, due_at = #{dueAt}, is_overdue = 0, update_by = #{updateBy}, updated_at = NOW()
WHERE stage_id = #{stageId}

mapper.select:
SELECT work_id AS workId, author_id AS authorId, status, title
FROM sys_work
WHERE work_id = #{workId}
